import{_ as d,o as e,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"工作流建模","description":"把业务流程落成 LangGraph.js 的状态通道、节点职责、路径分支与可验证终态，形成可实现的图模型。","frontmatter":{"title":"工作流建模","description":"把业务流程落成 LangGraph.js 的状态通道、节点职责、路径分支与可验证终态，形成可实现的图模型。","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"ts-ai/workflow/langgraph-core/workflow-modeling.md","filePath":"ts-ai/workflow/langgraph-core/workflow-modeling.md","lastUpdated":1786083160000}'),r={name:"ts-ai/workflow/langgraph-core/workflow-modeling.md"};function c(n,t,h,l,s,i){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="工作流建模" tabindex="-1">工作流建模 <a class="header-anchor" href="#工作流建模" aria-label="Permalink to &quot;工作流建模&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>在动手写 <code>StateGraph</code> 之前，先把业务说成<strong>显式状态 + 节点 + 路径 + 终态</strong>。建模质量决定后续 Reducer、路由和 Subgraph 是否好测；本篇只做模型，不展开 <code>compile</code> / <code>invoke</code> API。</p><p><strong>目标读者：</strong> 已读<a href="/ts-ai/workflow/workflow-foundations/">工作流基础</a>，准备把真实业务画成图。<br><strong>前置：</strong> <a href="/ts-ai/workflow/workflow-foundations/workflow-principles-boundaries">工作流原理与边界</a>、<a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a>。<br><strong>排除：</strong> Checkpoint、Interrupt、多 Agent 协作协议（见<a href="/ts-ai/workflow/durable-execution/">持久执行</a>与<a href="/ts-ai/workflow/multi-agent/">多 Agent</a>）。</p><h2 id="_1-建模解决什么问题" tabindex="-1">1. 建模解决什么问题 <a class="header-anchor" href="#_1-建模解决什么问题" aria-label="Permalink to &quot;1. 建模解决什么问题&quot;">​</a></h2><h3 id="_1-1-从业务叙事到可执行图" tabindex="-1">1.1 从业务叙事到可执行图 <a class="header-anchor" href="#_1-1-从业务叙事到可执行图" aria-label="Permalink to &quot;1.1 从业务叙事到可执行图&quot;">​</a></h3><p>业务常写成「先分类，再按类型处理，最后汇总」。图模型要求每一句都能落到四类对象之一：</p><table tabindex="0"><thead><tr><th>业务说法</th><th>图对象</th><th>建模问题</th></tr></thead><tbody><tr><td>「当前工单长什么样」</td><td>State 通道</td><td>哪些字段跨节点共享？谁可以改？</td></tr><tr><td>「做一次分类 / 查单 / 汇总」</td><td>Node</td><td>输入读哪些键？输出写哪些键？</td></tr><tr><td>「高优走 A，普通走 B」</td><td>Edge / 条件边</td><td>依据哪个通道决策？漏配怎么办？</td></tr><tr><td>「已答复 / 已拒绝 / 需人工」</td><td>终态（<code>END</code> 或业务状态）</td><td>如何证明一次 Run 已收敛？</td></tr></tbody></table><h3 id="_1-2-与-chain-agent-的分工" tabindex="-1">1.2 与 Chain / Agent 的分工 <a class="header-anchor" href="#_1-2-与-chain-agent-的分工" aria-label="Permalink to &quot;1.2 与 Chain / Agent 的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>控制流谁拥有</th><th>适合建模成图的信号</th></tr></thead><tbody><tr><td>Chain</td><td>编译期固定</td><td>无需；保持 <code>pipe</code></td></tr><tr><td><code>createAgent</code></td><td>模型选工具</td><td>步骤少、无强制分支签核</td></tr><tr><td>Workflow</td><td>你声明节点与边</td><td>分支、循环预算、并行汇聚、可测状态迁移</td></tr></tbody></table><p>若业务核心是「模型自由选工具」，先留在 Agent；若核心是「必须经过分类 → 分支 → 汇总且可断言状态」，再上图。选型见 <a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a>。</p><h2 id="_2-状态通道设计" tabindex="-1">2. 状态通道设计 <a class="header-anchor" href="#_2-状态通道设计" aria-label="Permalink to &quot;2. 状态通道设计&quot;">​</a></h2><h3 id="_2-1-只放跨节点共享的事实" tabindex="-1">2.1 只放跨节点共享的事实 <a class="header-anchor" href="#_2-1-只放跨节点共享的事实" aria-label="Permalink to &quot;2.1 只放跨节点共享的事实&quot;">​</a></h3><p>State 不是「整个业务数据库快照」，而是<strong>本图一次 Run 的工作集</strong>。典型通道：</p><table tabindex="0"><thead><tr><th>通道</th><th>含义</th><th>更新方式直觉</th></tr></thead><tbody><tr><td><code>ticketId</code> / <code>category</code></td><td>标量事实</td><td>后写覆盖</td></tr><tr><td><code>messages</code> / <code>notes</code></td><td>累积列表</td><td>需 Reducer 合并</td></tr><tr><td><code>step</code> / <code>attempts</code></td><td>控制计数</td><td>增量 Reducer</td></tr><tr><td><code>status</code></td><td>业务阶段</td><td>覆盖；终态可读</td></tr></tbody></table><p>问自己：若某字段只在一个节点内使用，就留在该节点局部变量，不要污染 State。</p><h3 id="_2-2-通道清单模板-填好示例" tabindex="-1">2.2 通道清单模板（填好示例） <a class="header-anchor" href="#_2-2-通道清单模板-填好示例" aria-label="Permalink to &quot;2.2 通道清单模板（填好示例）&quot;">​</a></h3><p>以「客服工单分流」为例：</p><table tabindex="0"><thead><tr><th>键</th><th>类型意图</th><th>谁写</th><th>谁读</th><th>合并策略</th></tr></thead><tbody><tr><td><code>rawText</code></td><td>string</td><td>入口</td><td><code>classify</code></td><td>覆盖</td></tr><tr><td><code>category</code></td><td><code>&quot;billing&quot; | &quot;tech&quot; | &quot;other&quot;</code></td><td><code>classify</code></td><td>路由 / 处理节点</td><td>覆盖</td></tr><tr><td><code>notes</code></td><td>string[]</td><td>各处理节点</td><td><code>summarize</code></td><td>concat Reducer</td></tr><tr><td><code>status</code></td><td><code>&quot;open&quot; | &quot;done&quot; | &quot;rejected&quot;</code></td><td>处理 / 汇总</td><td>调用方断言</td><td>覆盖</td></tr></tbody></table><p>未声明合并策略的列表通道，在并行写入时会被后写覆盖——这是建模阶段就要标出的风险，细节见 <a href="/ts-ai/workflow/langgraph-core/state-reducers">State 与 Reducer</a>。</p><h2 id="_3-节点职责切分" tabindex="-1">3. 节点职责切分 <a class="header-anchor" href="#_3-节点职责切分" aria-label="Permalink to &quot;3. 节点职责切分&quot;">​</a></h2><h3 id="_3-1-一个节点一件事" tabindex="-1">3.1 一个节点一件事 <a class="header-anchor" href="#_3-1-一个节点一件事" aria-label="Permalink to &quot;3.1 一个节点一件事&quot;">​</a></h3><p>节点函数契约：<code>(state) =&gt; Partial&lt;State&gt;</code>（可异步）。好的切分：</p><table tabindex="0"><thead><tr><th>节点</th><th>读</th><th>写</th><th>不做</th></tr></thead><tbody><tr><td><code>classify</code></td><td><code>rawText</code></td><td><code>category</code></td><td>不直接答复用户</td></tr><tr><td><code>handleBilling</code></td><td><code>ticketId</code>, <code>rawText</code></td><td><code>notes</code>, <code>status</code></td><td>不处理 tech</td></tr><tr><td><code>summarize</code></td><td><code>notes</code></td><td><code>summary</code>, <code>status</code></td><td>不再改 <code>category</code></td></tr></tbody></table><p>把「分类 + 查库 + 写答复」塞进单节点，会让条件路由与状态测试无法定位失败点。</p><h3 id="_3-2-副作用与纯状态更新" tabindex="-1">3.2 副作用与纯状态更新 <a class="header-anchor" href="#_3-2-副作用与纯状态更新" aria-label="Permalink to &quot;3.2 副作用与纯状态更新&quot;">​</a></h3><p>建模时区分：</p><ul><li><strong>纯更新</strong>：只改 State，易测。</li><li><strong>副作用</strong>：调 HTTP、写库、发邮件——记在节点职责旁，并规划幂等键（实现见<a href="/ts-ai/workflow/durable-execution/idempotency-replay">持久执行</a>）。</li></ul><p>本篇只要求你在模型表里标出「有副作用」，不要假装节点都是纯函数。</p><h2 id="_4-路径、分支与终态" tabindex="-1">4. 路径、分支与终态 <a class="header-anchor" href="#_4-路径、分支与终态" aria-label="Permalink to &quot;4. 路径、分支与终态&quot;">​</a></h2><h3 id="_4-1-路径表" tabindex="-1">4.1 路径表 <a class="header-anchor" href="#_4-1-路径表" aria-label="Permalink to &quot;4.1 路径表&quot;">​</a></h3><p>用表代替随意画线：</p><table tabindex="0"><thead><tr><th>从</th><th>到</th><th>类型</th><th>条件</th></tr></thead><tbody><tr><td><code>START</code></td><td><code>classify</code></td><td>固定边</td><td>—</td></tr><tr><td><code>classify</code></td><td><code>handleBilling</code></td><td>条件</td><td><code>category === &quot;billing&quot;</code></td></tr><tr><td><code>classify</code></td><td><code>handleTech</code></td><td>条件</td><td><code>category === &quot;tech&quot;</code></td></tr><tr><td><code>classify</code></td><td><code>reject</code></td><td>条件</td><td>其他</td></tr><tr><td><code>handleBilling</code> / <code>handleTech</code> / <code>reject</code></td><td><code>summarize</code></td><td>固定边</td><td>—</td></tr><tr><td><code>summarize</code></td><td><code>END</code></td><td>固定边</td><td>—</td></tr></tbody></table><p>条件边必须<strong>穷尽</strong>可到达类别，或显式落到 <code>reject</code> / <code>END</code>。漏配路由是运行期挂起或抛错的主因。</p><h3 id="_4-2-终态的可验证定义" tabindex="-1">4.2 终态的可验证定义 <a class="header-anchor" href="#_4-2-终态的可验证定义" aria-label="Permalink to &quot;4.2 终态的可验证定义&quot;">​</a></h3><p>终态不是「图跑完了」这一句空话，而是调用方可断言的状态谓词，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status === &quot;done&quot; &amp;&amp; typeof summary === &quot;string&quot; &amp;&amp; summary.length &gt; 0</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>status === &quot;rejected&quot; &amp;&amp; notes 含拒绝原因</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>循环场景还需预算：<code>attempts &lt; MAX</code> 否则强制 <code>END</code> 并写入 <code>status: &quot;exhausted&quot;</code>。循环预算实现见 <a href="/ts-ai/workflow/langgraph-core/loops-parallelism-aggregation">循环、并行与结果汇聚</a>。</p><h3 id="_4-3-状态变化轨迹-建模验收" tabindex="-1">4.3 状态变化轨迹（建模验收） <a class="header-anchor" href="#_4-3-状态变化轨迹-建模验收" aria-label="Permalink to &quot;4.3 状态变化轨迹（建模验收）&quot;">​</a></h3><p>实现前用轨迹表验收模型是否完整。假设输入 <code>rawText = &quot;发票金额不对&quot;</code>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>节点</th><th>State 关键变化</th></tr></thead><tbody><tr><td>0</td><td>（输入）</td><td><code>{ rawText, status: &quot;open&quot;, notes: [] }</code></td></tr><tr><td>1</td><td><code>classify</code></td><td><code>category: &quot;billing&quot;</code></td></tr><tr><td>2</td><td><code>handleBilling</code></td><td><code>notes: [&quot;已核对账单&quot;], status: &quot;resolved&quot;</code></td></tr><tr><td>3</td><td><code>summarize</code></td><td><code>summary: &quot;...&quot;, status: &quot;done&quot;</code></td></tr></tbody></table><p>若某条业务路径无法填满这张表，说明通道或节点仍缺定义。</p><h2 id="_5-建模边界与常见失败" tabindex="-1">5. 建模边界与常见失败 <a class="header-anchor" href="#_5-建模边界与常见失败" aria-label="Permalink to &quot;5. 建模边界与常见失败&quot;">​</a></h2><h3 id="_5-1-适用与不适用" tabindex="-1">5.1 适用与不适用 <a class="header-anchor" href="#_5-1-适用与不适用" aria-label="Permalink to &quot;5.1 适用与不适用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>适合立刻建模成图</th><th>暂缓上图</th></tr></thead><tbody><tr><td>分支固定、终态可断言</td><td>单次提示词生成</td></tr><tr><td>需要并行子任务再汇聚</td><td>工具 ≤2 的短对话 Agent</td></tr><tr><td>后续要状态迁移测试</td><td>尚无共享 State 约定的探索原型</td></tr></tbody></table><h3 id="_5-2-常见失败" tabindex="-1">5.2 常见失败 <a class="header-anchor" href="#_5-2-常见失败" aria-label="Permalink to &quot;5.2 常见失败&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>建模根因</th><th>修正</th></tr></thead><tbody><tr><td>节点越写越大</td><td>按「页面」而非「职责」切分</td><td>拆分类 / 处理 / 汇总</td></tr><tr><td>并行结果丢失</td><td>列表通道未标 Reducer</td><td>在通道表写明 concat</td></tr><tr><td>跑不完或随机停</td><td>终态谓词缺失或条件未穷尽</td><td>补 <code>reject</code> / 预算出口</td></tr><tr><td>与 Agent 职责打架</td><td>把「模型自由规划」硬编码成死路径</td><td>回到选型决策树</td></tr></tbody></table><h2 id="_6-下一步" tabindex="-1">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><ol><li>用通道表 + 路径表实现 <a href="/ts-ai/workflow/langgraph-core/state-graph"><code>StateGraph</code></a>。</li><li>为列表与并发通道配置 <a href="/ts-ai/workflow/langgraph-core/state-reducers">Reducer</a>。</li><li>把条件边与终止写成可测路由：<a href="/ts-ai/workflow/langgraph-core/nodes-edges-routing">Node、Edge 与条件路由</a>。</li><li>需要暂停恢复时进入<a href="/ts-ai/workflow/durable-execution/">持久执行</a>，不要在建模阶段假装已有 Checkpoint。</li></ol>`,49)])])}const b=d(r,[["render",c]]);export{p as __pageData,b as default};
